/home/cxz/.local/bin/micromamba run -n copper-foil-defect-classification bash -c $'set -euo pipefail\ncp "$DATA_PATH/../dataset_manifest.json" "$OUTPUT_DIR/dataset_manifest.json"\ncp "$DATA_PATH/../upload_receipt.json" "$OUTPUT_DIR/upload_receipt.json"\npython - <<\'PY\'\nimport hashlib, json, os, zipfile\nfrom pathlib import Path\nroot = Path(os.environ[\'PROJECT_ROOT\'])\noutput = Path(os.environ[\'OUTPUT_DIR\'])\nreceipt = json.loads((output/\'upload_receipt.json\').read_text())\nassert receipt[\'verified\'] and receipt[\'admissible_images\'] == 31317 and receipt[\'excluded_non_200x200\'] == 138\nbundle = root/\'experiments/20261024T014207Z-20261024-0942-7classes-minimal-deployment-verify/copper-foil-7class-20261024.zip\'\ndef sha(path):\n    digest = hashlib.sha256()\n    with path.open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024*1024), b\'\'):\n            digest.update(block)\n    return digest.hexdigest()\nassert sha(bundle) == \'f6a63a80b51bf099c174c8bac9feeb0cb4671f502e16d3d09e4d6c1c68fe7e23\'\nwith zipfile.ZipFile(bundle) as archive:\n    prefix = \'copper-foil-7class/\'\n    manifest = json.loads(archive.read(prefix+\'PACKAGE_MANIFEST.json\'))\n    labels = archive.read(prefix+\'configs/class_labels_csd.txt\')\n    for name in [\'infer_topk.py\',\'datasets.py\',\'models/self/convnextv2_modified.py\',\'models/utils.py\']:\n        assert sha(root/name) == manifest[\'files\'][name][\'sha256\'], name\nassert hashlib.sha256(labels).hexdigest() == \'5b18a8b194c3d417e97590ca2dd51c0da5e17853fb1e9be158b2a4e94bfa5670\'\n(output/\'class_labels_csd.txt\').write_bytes(labels)\ncheckpoint = root/\'experiments/20261023T150120Z-20261023-2301-1017-301-dedup-7classes-train/checkpoint-best.pth\'\nassert sha(checkpoint) == manifest[\'checkpoint_sha256\'] == \'8b8bce7c740320e5fe46ad82a2e4495a4760f6e6030fd9045123eafaf562b489\'\nprovenance = {\'checkpoint\':str(checkpoint), \'checkpoint_sha256\':manifest[\'checkpoint_sha256\'],\n              \'classes\':manifest[\'classes\'], \'class_labels_sha256\':manifest[\'class_labels_sha256\'],\n              \'runtime_matches_verified_deployment_package\':True, \'non200_policy\':\'skip_and_preserve_originals\',\n              \'k\':3,\'conf\':0.7,\'batch_size\':64,\'num_workers\':10,\'seed\':0,\'amp\':True}\n(output/\'model_provenance.json\').write_text(json.dumps(provenance,ensure_ascii=False,indent=2)+\'\\n\',encoding=\'utf-8\')\nPY\npython infer_topk.py --data "$DATA_PATH" --output "$OUTPUT_DIR/inference" \\\n  --checkpoint "$PROJECT_ROOT/experiments/20261023T150120Z-20261023-2301-1017-301-dedup-7classes-train/checkpoint-best.pth" \\\n  --class-labels "$OUTPUT_DIR/class_labels_csd.txt" --k 3 --conf 0.7 \\\n  --batch-size 64 --num-workers 10 --seed 0 --amp true \\\n  > "$OUTPUT_DIR/inference_stdout.jsonl" 2> "$OUTPUT_DIR/inference_stderr.log"\npython scripts/organize-inference-results.py --data "$DATA_PATH" \\\n  --predictions "$OUTPUT_DIR/inference/all_predictions.jsonl" \\\n  --summary "$OUTPUT_DIR/inference/summary.json" --manifest "$OUTPUT_DIR/dataset_manifest.json" \\\n  --class-labels "$OUTPUT_DIR/class_labels_csd.txt" --output "$OUTPUT_DIR" \\\n  > "$OUTPUT_DIR/organization.log"\npython - <<\'PY\'\nimport csv, hashlib, json, os\nfrom collections import Counter\nfrom pathlib import Path\noutput=Path(os.environ[\'OUTPUT_DIR\'])\nsummary=json.loads((output/\'inference/summary.json\').read_text())\norganized=json.loads((output/\'organization_summary.json\').read_text())\nlow=json.loads((output/\'low_confidence_top3.json\').read_text())\npredictions=[json.loads(line) for line in (output/\'inference/all_predictions.jsonl\').read_text().splitlines()]\nwith (output/\'top1_predictions.csv\').open(newline=\'\') as stream:\n    rows=list(csv.DictReader(stream))\nwith (output/\'inference/excluded_non_200x200.csv\').open(newline=\'\') as stream:\n    excluded=list(csv.DictReader(stream))\nassert len(rows)==len(predictions)==summary[\'samples\']==organized[\'classified_images\']==31317\nassert len(excluded)==summary[\'excluded_non_200x200\']==138\nassert summary[\'labeled_samples\']==0 and summary[\'accuracy\'] is None\nassert len({r[\'source_path\'] for r in rows})==31317\ncounts=Counter()\nfor row in rows:\n    path=output/row[\'organized_path\']\n    assert path.is_file() and path.relative_to(output/\'by_top1\').parts[0]==row[\'top1_label\']\n    counts[row[\'top1_label\']]+=1\nassert dict(counts)=={k:v for k,v in organized[\'per_class\'].items() if v}\nassert len([p for p in (output/\'by_top1\').rglob(\'*\') if p.is_file()])==31317\nlow_predictions={p[\'path\']:p for p in predictions if p[\'top1_conf\']<0.7}\nassert len(low_predictions)==low[\'samples\']==len(low[\'records\'])==organized[\'low_confidence_samples\']\nfor row in low[\'records\']:\n    original=low_predictions[str(Path(summary[\'data\'])/row[\'source_path\'])]\n    assert row[\'top3\']==original[\'topk\'] and row[\'top1_conf\']==original[\'top1_conf\']\n    assert len(row[\'top3\'])==3\nassert len(list((output/\'by_top1\').iterdir()))==7\nverification={\'verified\':True,\'classified_images\':31317,\'excluded_non_200x200\':138,\n              \'non_image_files_preserved\':3,\'per_class\':organized[\'per_class\'],\n              \'low_confidence_samples\':low[\'samples\'],\'low_confidence_per_class\':organized[\'low_confidence_per_class\'],\n              \'all_copied_image_hashes_verified\':organized[\'all_copied_image_hashes_verified\'],\n              \'strict_conf\':0.7,\'k\':3,\'no_ground_truth_accuracy\':True,\n              \'low_confidence_json_sha256\':hashlib.sha256((output/\'low_confidence_top3.json\').read_bytes()).hexdigest()}\n(output/\'verification.json\').write_text(json.dumps(verification,ensure_ascii=False,indent=2)+\'\\n\',encoding=\'utf-8\')\nprint(json.dumps(verification,ensure_ascii=False,indent=2))\nPY\r' 
